begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
delete from public.user_profiles;
insert into auth.users(id,email,email_confirmed_at) values ('81000000-0000-0000-0000-000000000001','refinements@kapa.test',now());
insert into public.user_profiles(user_id,partner_id,display_name) select '81000000-0000-0000-0000-000000000001',id,'John' from public.partners where code='john';
update public.business_settings set energy_kwh_cost=0,labor_hour_cost=0;
create function pg_temp.op(action text,p jsonb) returns jsonb language sql as $$select public.business_operate(action,p,gen_random_uuid())$$;
create function pg_temp.line_id(n text) returns uuid language sql as $$select id from public.order_lines where description=n$$;
create function pg_temp.ver() returns integer language sql as $$select version from public.orders where id='85000000-0000-0000-0000-000000000001'$$;
create temp table refinement_fixture(k text primary key,v jsonb);
insert into refinement_fixture values('piece','{"description":"Llaveros NFC","quantity":"2","printer_id":"82000000-0000-0000-0000-000000000001","hours":"1.5","materials":[{"lot_id":"83000000-0000-0000-0000-000000000001","piece_grams":"10"}],"extra_items":[{"description":"Chip NFC","quantity":"2","unit_cost":"500"}],"multiplier":"3"}');
grant select on refinement_fixture to authenticated;
set local request.jwt.claim.sub='81000000-0000-0000-0000-000000000001';
set local role authenticated;
select is((public.business_read('capabilities')->>'schema_version')::integer,3,'La interfaz puede comprobar la versión del servidor antes de guardar');
select lives_ok($$select pg_temp.op('lot_purchase','{"id":"83000000-0000-0000-0000-000000000001","brand":"Refinamientos","kind":"PLA","color":"Vinotinto","initial_grams":"1000","total":"90000","paid":"0","financing":"credit_card","installments":"3","installment_interest":"100","description":"Tarjeta filamento"}')$$,'Compra con tarjeta financiada sin caja inicial');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,0::numeric,'Financiar no genera caja negativa');
select is((select financing from public.debts where description='Tarjeta filamento'),'credit_card','La deuda identifica tarjeta de crédito');
select is((select financing from public.purchases where description='Tarjeta filamento'),'credit_card','La compra identifica tarjeta de crédito');
select lives_ok($$select pg_temp.op('opening_save',jsonb_build_object('version',(select version from public.opening_balances),'income','100','expense','40','cash_amount','60','notes','Saldos anteriores a KAPA'))$$,'Configurar ingresos, gastos y caja inicial independientes');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,60::numeric,'Caja incluye solo el saldo inicial una vez');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,60::numeric,'Resultado inicial incluye ingresos menos gastos');
select throws_ok($$select pg_temp.op('opening_save','{"version":1,"income":999,"expense":0,"notes":"Edición desactualizada"}')$$,'PT409',null,'Saldos iniciales tienen control de versión');
select lives_ok($$select pg_temp.op('printer_save','{"id":"82000000-0000-0000-0000-000000000001","name":"Prueba refinamientos","model":"A1","acquisition_cost":"0","useful_hours":"1000","power_kw":"0"}');select pg_temp.op('customer_save','{"id":"84000000-0000-0000-0000-000000000001","name":"Cliente personalizado"}')$$,'Preparar recursos configurados');
select is((public.preview_production_cost((select v from refinement_fixture where k='piece'))->>'total')::numeric,1900::numeric,'Costea 10g y dos chips NFC, una sola vez');
select is((public.preview_production_cost((select v from refinement_fixture where k='piece'))->>'extras_cost')::numeric,1000::numeric,'Los insumos tienen cantidad y costo unitario');
select throws_ok($$select public.preview_production_cost((select v from refinement_fixture where k='piece')||'{"extra_items":[{"description":"","quantity":1,"unit_cost":500}]}')$$,'22023',null,'No admite insumos sin descripción');
select lives_ok($$select pg_temp.op('quote_create',jsonb_build_object('id','86000000-0000-0000-0000-000000000001','customer_id','84000000-0000-0000-0000-000000000001','description','Varias piezas personalizadas','lines',jsonb_build_array((select v from refinement_fixture where k='piece'),(select v from refinement_fixture where k='piece')||'{"description":"Otra pieza","quantity":"1","hours":"0.25","extra_items":[],"materials":[{"lot_id":"83000000-0000-0000-0000-000000000001","piece_grams":"5"}]}')))$$,'Cotización de varias piezas sin productos de catálogo');
select is((select price_total from public.quotes where id='86000000-0000-0000-0000-000000000001'),12750::numeric,'Suma cantidades, materiales y extras por pieza');
select ok(not exists(select 1 from public.quote_lines where product_id is not null),'Catálogo completamente opcional');
select lives_ok($$select pg_temp.op('quote_update',jsonb_build_object('id','86000000-0000-0000-0000-000000000001','version',1,'customer_id','84000000-0000-0000-0000-000000000001','description','Cotización editada','lines',jsonb_build_array((select v from refinement_fixture where k='piece'),(select v from refinement_fixture where k='piece')||'{"description":"Otra pieza","quantity":"1","hours":"0.25","extra_items":[],"materials":[{"lot_id":"83000000-0000-0000-0000-000000000001","piece_grams":"5"}]}')))$$,'Editar cotización antes de convertirla');
select is((select version from public.quotes where id='86000000-0000-0000-0000-000000000001'),2,'Cotización avanza versión');
select lives_ok($$select pg_temp.op('order_create','{"id":"85000000-0000-0000-0000-000000000001","quote_id":"86000000-0000-0000-0000-000000000001","promised_at":"2030-02-01T12:00:00-05:00"}')$$,'Convertir piezas sin perder costos');
select throws_ok($$select pg_temp.op('quote_update',jsonb_build_object('id','86000000-0000-0000-0000-000000000001','version',2,'lines',jsonb_build_array((select v from refinement_fixture where k='piece'))))$$,'PT409',null,'La cotización convertida conserva el original');
select lives_ok($$select pg_temp.op('order_edit',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver(),'customer_id','84000000-0000-0000-0000-000000000001','description','Pedido editado'))$$,'Editar datos del pedido');
select lives_ok($$select pg_temp.op('order_line_save',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver(),'line_id',pg_temp.line_id('Llaveros NFC'),'description','Llaveros NFC','quantity',2,'unit_price',6000))$$,'Editar cantidad y precio de una pieza');
select lives_ok($$select pg_temp.op('order_line_save',(select v from refinement_fixture where k='piece')||jsonb_build_object('description','Pieza adicional','quantity',1,'order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver()))$$,'Añadir una pieza personalizada al pedido');
select lives_ok($$select pg_temp.op('order_line_remove',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver(),'line_id',pg_temp.line_id('Pieza adicional')))$$,'Quitar pieza sin historial');
select is((select price_total from public.orders where id='85000000-0000-0000-0000-000000000001'),13350::numeric,'Edición recalcula total del pedido');
select lives_ok($$select pg_temp.op('order_payment',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','line_id',pg_temp.line_id('Llaveros NFC'),'amount',6000))$$,'Asignar anticipo a la pieza elegida');
select is((public.business_read('orders')->'rows'->0->'lines' @> '[{"description":"Llaveros NFC","paid":6000}]'),true,'Lectura muestra el anticipo por pieza');
select throws_ok($$select pg_temp.op('order_payment',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','line_id',pg_temp.line_id('Otra pieza'),'amount',2000))$$,'PT422',null,'Cobro a pieza equivocada se revierte completo');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,6060::numeric,'Error de asignación no deja dinero fantasma');
select lives_ok($$select pg_temp.op('order_update',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver(),'status','confirmed','confirm_without_deposit',true))$$,'Confirmar y reservar varias piezas');
select is((select sum(grams) from public.material_reservations),25::numeric,'Reserva materiales de todas las piezas');
reset role;
update public.orders set created_at=now()-interval '4 days' where id='85000000-0000-0000-0000-000000000001';
set local role authenticated;
select is(jsonb_array_length(public.business_read('dashboard')->'alerts'->'stale_orders'),1,'Alerta pedidos de más de tres días sin producir');
select lives_ok($$select pg_temp.op('production_create',(select v from refinement_fixture where k='piece')||jsonb_build_object('line_id',pg_temp.line_id('Llaveros NFC'),'good_units',1,'hours','0.75'))$$,'Producir la primera unidad con insumos reales');
select is(jsonb_array_length(public.business_read('dashboard')->'alerts'->'stale_orders'),0,'La alerta desaparece cuando se registra producción real');
select lives_ok($$select pg_temp.op('line_deliver',jsonb_build_object('line_id',pg_temp.line_id('Llaveros NFC'),'version',pg_temp.ver(),'delivered_quantity',1))$$,'Entregar una unidad pagada sin cerrar el pedido completo');
select is((select delivered_quantity from public.order_lines where description='Llaveros NFC'),1,'Conserva progreso de entrega por pieza');
select is((public.business_read('receivables')->>'total')::integer,0,'Una unidad entregada y cubierta no es cuenta por cobrar');
select lives_ok($$select pg_temp.op('production_create',(select v from refinement_fixture where k='piece')||jsonb_build_object('line_id',pg_temp.line_id('Llaveros NFC'),'good_units',1,'hours','0.75'))$$,'Producir la segunda unidad');
select lives_ok($$select pg_temp.op('line_deliver',jsonb_build_object('line_id',pg_temp.line_id('Llaveros NFC'),'version',pg_temp.ver(),'delivered_quantity',2))$$,'Entregar segunda unidad a crédito');
select is((public.business_read('receivables')->>'total')::integer,1,'Apartado entregado por cobrar incluye entrega parcial pendiente');
select is((public.business_read('cash')->'summary'->>'delivered_receivables')::numeric,6000::numeric,'Solo el valor entregado no cubierto es cartera entregada');
select throws_ok($$select pg_temp.op('order_delete',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver(),'reason','Intento con deuda pendiente'))$$,'PT422',null,'Eliminar no borra deudas del cliente');
select throws_ok($$select pg_temp.op('order_line_save',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver(),'line_id',pg_temp.line_id('Llaveros NFC'),'description','Llaveros NFC','quantity',1,'unit_price',6000))$$,'PT422',null,'Editar no reduce unidades ya producidas o entregadas');
select lives_ok($$select pg_temp.op('experiment_create','{"kind":"test","description":"Calibración sin venta","printer_id":"82000000-0000-0000-0000-000000000001","hours":"0","minutes":"30","materials":[{"lot_id":"83000000-0000-0000-0000-000000000001","grams":"2"}]}')$$,'Prueba sin venta consume solo material y admite minutos');
select is((select material_cost from public.print_experiments),180::numeric,'Prueba reconoce solo costo material');
select is((select actual_hours from public.print_experiments),0.5::numeric,'30 minutos equivalen a media hora');
select is((select on_hand_grams from public.inventory_lots),978::numeric,'Stock descuenta producción y prueba una vez');
select throws_ok($$select pg_temp.op('inventory_reverse',jsonb_build_object('movement_id',(select id from public.inventory_movements where experiment_id is not null),'reason','No se puede corregir doble'))$$,'PT422',null,'Impide compensar prueba desde dos módulos diferentes');
select lives_ok($$select pg_temp.op('experiment_reverse',jsonb_build_object('experiment_id',(select id from public.print_experiments),'reason','Registro de prueba equivocado'))$$,'Compensar registro equivocado de prueba');
select is((select on_hand_grams from public.inventory_lots),980::numeric,'Compensación recupera solo material de la prueba');
select lives_ok($$select pg_temp.op('inventory_count','{"lot_id":"83000000-0000-0000-0000-000000000001","previous_grams":"980","on_hand_grams":"970","reason":"Conteo físico verificado"}')$$,'Modificar cantidad actual sin calcular deltas manualmente');
select is((select on_hand_grams from public.inventory_lots),970::numeric,'Cantidad actual coincide con conteo');
select throws_ok($$select pg_temp.op('inventory_count','{"lot_id":"83000000-0000-0000-0000-000000000001","previous_grams":"980","on_hand_grams":"960","reason":"Conteo desactualizado"}')$$,'PT409',null,'Impide sobrescribir consumo que cambió durante conteo');
select lives_ok($$select pg_temp.op('debt_pay',jsonb_build_object('debt_id',(select id from public.debts),'principal','1000','interest','100'))$$,'Pagar capital e interés de tarjeta por separado');
select is((public.business_read('cash')->'summary'->>'cash')::numeric,4960::numeric,'Solo cuota efectivamente pagada reduce caja');
select is((public.business_read('cash',p_from:=(now() at time zone 'America/Bogota')::date,p_to:=((now() at time zone 'America/Bogota')::date+interval '2 months')::date)->'summary'->>'installments_paid')::numeric,1100::numeric,'Resumen incluye cuotas de tarjeta pagadas');
select lives_ok($$select pg_temp.op('order_payment',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','line_id',pg_temp.line_id('Llaveros NFC'),'amount',6000));select pg_temp.op('order_payment',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','line_id',pg_temp.line_id('Otra pieza'),'amount',1350))$$,'Cobrar por separado saldos de ambas piezas');
select is((public.business_read('receivables')->>'total')::integer,0,'Cobrar una entrega la elimina de cartera entregada');
select lives_ok($$select pg_temp.op('production_create',jsonb_build_object('line_id',pg_temp.line_id('Otra pieza'),'good_units',1,'hours','0.25','materials','[{"lot_id":"83000000-0000-0000-0000-000000000001","piece_grams":"5"}]'::jsonb));select pg_temp.op('line_deliver',jsonb_build_object('line_id',pg_temp.line_id('Otra pieza'),'version',pg_temp.ver(),'delivered_quantity',1))$$,'Completar entrega de las distintas piezas');
select is((select status from public.orders where id='85000000-0000-0000-0000-000000000001'),'delivered','El pedido se cierra cuando todas las piezas están entregadas');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,8160::numeric,'Utilidad incluye todos los insumos reales, conteo, saldo inicial e interés una vez');
select is((public.business_read('cash',p_from:=(now() at time zone 'America/Bogota')::date,p_to:=((now() at time zone 'America/Bogota')::date+30))->'summary'->>'after_installments')::numeric,(-21840)::numeric,'Presupuesto resta capital pagado y cuotas pendientes sin repetir intereses');
select lives_ok($$select public.business_report('deliveries',current_date-1,current_date);select public.business_report('experiments',current_date-1,current_date);select public.business_report('opening',current_date-1,current_date);select public.business_report('installments',current_date-1,current_date+60)$$,'Reportes incluyen piezas, pruebas, cuotas y saldos iniciales');
select lives_ok($$select pg_temp.op('order_delete',jsonb_build_object('order_id','85000000-0000-0000-0000-000000000001','version',pg_temp.ver(),'reason','Archivar pedido completado'))$$,'Eliminar pedido cerrado de las vistas de trabajo');
select is((public.business_read('orders')->>'total')::integer,0,'Pedido eliminado no aparece en lista ni calendario');
select is((select count(*) from public.orders),1::bigint,'El historial contable permanece tras eliminar');
select is((public.business_read('dashboard')->'summary'->>'cumulative_profit')::numeric,8160::numeric,'Eliminar no cambia la utilidad ni borra consumos');
select throws_ok($$select pg_temp.op('cash_reverse',jsonb_build_object('cash_id',(select id from public.cash_entries where category='deposit' limit 1),'reason','No se cambia un archivo cerrado'))$$,'PT422',null,'No crea cartera oculta al revertir cobro de un pedido archivado');
select lives_ok($$select pg_temp.op('experiment_create','{"kind":"failed","description":"Fallo fuera de pedido","materials":[{"lot_id":"83000000-0000-0000-0000-000000000001","grams":"1"}]}')$$,'Fallo sin pedido registra gasto material sin venta');
select is((public.business_report('experiments',current_date-1,current_date)->'rows'->1->>'venta')::numeric,0::numeric,'Impresiones fallidas no inventan ventas');
reset role;
set local request.jwt.claim.sub='81000000-0000-0000-0000-000000000002';
set local role authenticated;
select is((select count(*) from public.order_line_payments),0::bigint,'Terceros no leen cobros por pieza');
select is((select count(*) from public.opening_balances),0::bigint,'Terceros no leen saldos iniciales');
select throws_ok($$select public.business_operate('experiment_create','{}',gen_random_uuid())$$,'42501',null,'Terceros no registran consumos');
reset role;
select is(private.op_cash_balance(),12310::numeric,'Caja incluye saldo inicial y cobros menos cuota sin cargo por consumo');
select * from finish();
rollback;
